async function fetchCurrentAirQuality(latitude = selectedAirLocation.latitude, longitude = selectedAirLocation.longitude) {
  const requestId = ++airQualityRequestId;
  airQualityState = "loading";
  renderAirQualityStatus();
  renderSmartAlerts();
  const refreshButton = document.querySelector("#refresh-air-data");
  refreshButton.disabled = true;
  if (!currentAirQuality) {
    clearAirQualityDisplay();
    document.querySelector("#aqi-category").textContent = currentLanguage === "hi" ? "लाइव डेटा लोड हो रहा है…" : "Loading live data…";
    document.querySelector("#aqi-description").textContent = currentLanguage === "hi"
      ? "Open-Meteo से वर्तमान वायु गुणवत्ता प्राप्त की जा रही है…"
      : "Fetching current air quality from Open-Meteo…";
  }
  document.querySelector("#aqi-updated").textContent = currentLanguage === "hi" ? "लाइव डेटा लोड हो रहा है…" : "Loading live data…";

  const query = new URLSearchParams({
    latitude: String(latitude),
    longitude: String(longitude),
    current: "pm10,pm2_5,nitrogen_dioxide,ozone,us_aqi",
    timezone: "auto"
  });
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 15000);
  try {
    const response = await fetch(`https://air-quality-api.open-meteo.com/v1/air-quality?${query}`, {
      signal: controller.signal,
      cache: "no-store"
    });
    if (!response.ok) throw new Error(`Open-Meteo returned HTTP ${response.status}`);
    const data = await response.json();
    if (!data.current || !Number.isFinite(data.current.us_aqi) || typeof data.current.time !== "string"
      || !Number.isFinite(data.latitude) || !Number.isFinite(data.longitude) || typeof data.timezone !== "string") {
      throw new Error("Open-Meteo response is missing current AQI or location metadata");
    }
    if (requestId !== airQualityRequestId) return;
    currentAirQuality = data;
    renderAirQuality(data);
    console.info("AirGuard loaded current air quality.", {
      aqi: data.current.us_aqi,
      time: data.current.time,
      timezone: data.timezone,
      coordinates: [data.latitude, data.longitude]
    });
  } catch (error) {
    if (requestId !== airQualityRequestId) return;
    currentAirQuality = null;
    airQualityState = "error";
    clearAirQualityDisplay();
    renderAirQualityStatus();
    console.error("AirGuard could not load live air quality.", error);
    document.querySelector("#aqi-updated").textContent = currentLanguage === "hi"
      ? "लाइव AQI लोड नहीं हो सका"
      : "Could not load live AQI";
  } finally {
    clearTimeout(timeout);
    if (requestId === airQualityRequestId) refreshButton.disabled = false;
  }
}

function renderTimelineStatus() {
  const status = document.querySelector("#trend-status");
  status.classList.remove("status-loading", "status-live", "status-error");
  if (airQualityTimelineState === "loading") {
    status.classList.add("status-loading");
    status.textContent = dashboardLabels[currentLanguage].trendLoading;
  } else if (airQualityTimelineState === "error") {
    status.classList.add("status-error");
    status.textContent = dashboardLabels[currentLanguage].trendApiUnavailable;
  } else {
    const points = getTrendPoints(currentRange);
    if (!points.length) {
      status.classList.add("status-error");
      status.textContent = dashboardLabels[currentLanguage].trendUnavailable;
    } else {
      status.classList.add("status-live");
      const firstTime = points[0].startTime || points[0].time;
      const lastTime = points[points.length - 1].endTime || points[points.length - 1].time;
      status.textContent = `${firstTime.replace("T", " ")} — ${lastTime.replace("T", " ")} · ${airQualityTimeline.timezone}`;
    }
  }
}

async function fetchAirQualityTimeline(latitude = selectedAirLocation.latitude, longitude = selectedAirLocation.longitude) {
  const requestId = ++airQualityTimelineRequestId;
  airQualityTimeline = null;
  airQualityTimelineState = "loading";
  renderTimelineStatus();
  renderChart(currentRange);
  renderForecast();

  const query = new URLSearchParams({
    latitude: String(latitude),
    longitude: String(longitude),
    current: "us_aqi,pm2_5",
    hourly: "us_aqi,pm2_5",
    past_days: "30",
    forecast_days: "2",
    timezone: "auto"
  });
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 20000);
  try {
    const response = await fetch(`https://air-quality-api.open-meteo.com/v1/air-quality?${query}`, {
      signal: controller.signal,
      cache: "no-store"
    });
    if (!response.ok) throw new Error(`Open-Meteo returned HTTP ${response.status}`);
    const data = await response.json();
    if (!data.current || typeof data.current.time !== "string"
      || !Number.isFinite(data.latitude) || !Number.isFinite(data.longitude)
      || typeof data.timezone !== "string" || !data.hourly
      || !Array.isArray(data.hourly.time) || !Array.isArray(data.hourly.us_aqi)
      || !Array.isArray(data.hourly.pm2_5)
      || data.hourly.time.length !== data.hourly.us_aqi.length
      || data.hourly.time.length !== data.hourly.pm2_5.length) {
      throw new Error("Open-Meteo response is missing timestamped AQI/PM2.5 series");
    }
    if (requestId !== airQualityTimelineRequestId) return;
    airQualityTimeline = data;
    airQualityTimelineState = "live";
    renderTimelineStatus();
    renderChart(currentRange);
    renderForecast();
    console.info("AirGuard loaded timestamped CAMS air-quality history and forecast.", {
      timezone: data.timezone,
      coordinates: [data.latitude, data.longitude],
      firstTime: data.hourly.time[0],
      lastTime: data.hourly.time[data.hourly.time.length - 1],
      hourlySamples: data.hourly.time.length
    });
  } catch (error) {
    if (requestId !== airQualityTimelineRequestId) return;
    airQualityTimeline = null;
    airQualityTimelineState = "error";
    renderTimelineStatus();
    renderChart(currentRange);
    renderForecast();
    console.error("AirGuard could not load timestamped CAMS air-quality history and forecast.", error);
  } finally {
    clearTimeout(timeout);
  }
}

