    66: ["Light freezing rain", "हल्की जमने वाली बारिश", "rain"],
    67: ["Heavy freezing rain", "तेज़ जमने वाली बारिश", "rain"],
    71: ["Slight snow", "हल्की बर्फ़बारी", "snow"],
    73: ["Moderate snow", "मध्यम बर्फ़बारी", "snow"],
    75: ["Heavy snow", "तेज़ बर्फ़बारी", "snow"],
    77: ["Snow grains", "बर्फ़ के कण", "snow"],
    80: ["Slight rain showers", "हल्की बौछारें", "rain"],
