function renderWeatherStatus(state, data = currentWeather) {
  const status = document.querySelector("#weather-status");
  status.classList.remove("status-loading", "status-live", "status-error");
  if (state === "live" && data) {
    status.classList.add("status-live");
    const updated = `${data.current.time.replace("T", " ")} · ${data.timezone}`;
    status.textContent = currentLanguage === "hi"
      ? `Open-Meteo मॉडल · ${updated}`
      : `OPEN-METEO MODEL · ${updated}`;
    status.title = currentLanguage === "hi"
      ? "Open-Meteo मौसम मॉडल का अनुमान, स्थानीय मौसम स्टेशन की रीडिंग नहीं।"
      : "Open-Meteo weather model estimate, not a local weather station reading.";
  } else if (state === "error") {
    status.classList.add("status-error");
    status.textContent = currentLanguage === "hi" ? "मौसम उपलब्ध नहीं" : "WEATHER UNAVAILABLE";
    status.title = currentLanguage === "hi" ? "वर्तमान मौसम डेटा प्राप्त नहीं हो सका।" : "Current weather data could not be loaded.";
  } else {
    status.classList.add("status-loading");
    status.textContent = currentLanguage === "hi" ? "मौसम लोड हो रहा है…" : "Loading weather…";
    status.title = "";
  }
}

function renderWeather(data) {
  const current = data.current;
  const condition = weatherCondition(current.weather_code);
  document.querySelector("#weather-temperature").textContent = Number(current.temperature_2m).toFixed(1);
  document.querySelector("#weather-condition").textContent = condition[currentLanguage === "hi" ? 1 : 0];
  document.querySelector("#weather-humidity").textContent = String(Math.round(current.relative_humidity_2m));
  document.querySelector("#weather-wind").textContent = Number(current.wind_speed_10m).toFixed(1);
  document.querySelector("#weather-visibility").textContent = Number.isFinite(current.visibility)
    ? (current.visibility / 1000).toFixed(1)
    : "--";
  document.querySelector(".weather-symbol").dataset.condition = condition[2];
  weatherState = "live";
  renderWeatherStatus(weatherState, data);
}

function clearWeatherDisplay() {
  document.querySelector("#weather-temperature").textContent = "--";
  document.querySelector("#weather-condition").textContent = currentLanguage === "hi"
    ? (weatherState === "error" ? "मौसम उपलब्ध नहीं" : "लोड हो रहा है…")
    : (weatherState === "error" ? "Weather unavailable" : "Loading weather…");
  document.querySelector("#weather-humidity").textContent = "--";
  document.querySelector("#weather-wind").textContent = "--";
  document.querySelector("#weather-visibility").textContent = "--";
  document.querySelector(".weather-symbol").dataset.condition = "unknown";
}

