function renderPollutionMap() {
  const pointsElement = document.querySelector("#map-points");
  const statusElement = document.querySelector("#map-status");
  const locationElement = document.querySelector("#map-location-label");
  const sourceElement = document.querySelector("#map-source-note");
  const map = document.querySelector("#aqi-map");
  const strings = dashboardLabels[currentLanguage];

  pointsElement.replaceChildren();
  statusElement.classList.remove("status-loading", "status-live", "status-error");
  locationElement.textContent = selectedAirLocation.name[currentLanguage];
  sourceElement.textContent = strings.mapModelOnly;
  map.setAttribute("aria-label", currentLanguage === "hi"
    ? `${selectedAirLocation.name.hi} के आसपास CAMS मॉडल ग्रिड अनुमान, मॉनिटरिंग स्टेशन नहीं`
    : `CAMS model grid estimates near ${selectedAirLocation.name.en}; not monitoring stations`);

  if (pollutionMapState === "loading") {
    statusElement.classList.add("status-loading");
    statusElement.textContent = strings.mapLoading;
    return;
  }
  if (pollutionMapState === "error" || !pollutionMapData.length) {
    statusElement.classList.add("status-error");
    statusElement.textContent = strings.mapUnavailable;
    pointsElement.textContent = currentLanguage === "hi"
      ? "CAMS मॉडल ग्रिड डेटा लोड नहीं हो सका।"
      : "CAMS model grid data could not be loaded.";
    return;
  }

  statusElement.classList.add(pollutionMapState === "partial" ? "status-error" : "status-live");
  statusElement.textContent = pollutionMapState === "partial"
    ? strings.mapPartial
    : `${strings.mapModel} · ${pollutionMapData[0].current.time.replace("T", " ")}`;

  const latitudes = pollutionMapData.map((point) => point.latitude);
  const longitudes = pollutionMapData.map((point) => point.longitude);
  const minLatitude = Math.min(...latitudes);
  const maxLatitude = Math.max(...latitudes);
  const minLongitude = Math.min(...longitudes);
  const maxLongitude = Math.max(...longitudes);
  pollutionMapData.forEach((point) => {
    const marker = document.createElement("button");
    const x = maxLongitude === minLongitude ? 50 : 12 + (point.longitude - minLongitude) / (maxLongitude - minLongitude) * 76;
    const y = maxLatitude === minLatitude ? 50 : 14 + (maxLatitude - point.latitude) / (maxLatitude - minLatitude) * 64;
    const aqi = Math.round(point.current.us_aqi);
    const coordinates = formatCoordinates(point.latitude, point.longitude);
    const description = currentLanguage === "hi"
      ? `CAMS मॉडल अनुमानित US AQI ${aqi}; ग्रिड ${coordinates}; PM2.5 ${Number(point.current.pm2_5).toFixed(1)} और PM10 ${Number(point.current.pm10).toFixed(1)} माइक्रोग्राम प्रति घन मीटर`
      : `CAMS model-estimated US AQI ${aqi}; grid ${coordinates}; PM2.5 ${Number(point.current.pm2_5).toFixed(1)} and PM10 ${Number(point.current.pm10).toFixed(1)} micrograms per cubic meter`;
    marker.type = "button";
    marker.className = "aqi-map-marker";
    marker.style.left = `${x}%`;
    marker.style.top = `${y}%`;
    marker.dataset.category = aqi <= 50 ? "good" : aqi <= 100 ? "moderate" : aqi <= 150 ? "sensitive" : aqi <= 200 ? "unhealthy" : aqi <= 300 ? "very-unhealthy" : "hazardous";
    marker.textContent = String(aqi);
    marker.title = description;
    marker.setAttribute("aria-label", description);
    marker.addEventListener("click", () => showToast(description));
    pointsElement.append(marker);
  });
  if (pollutionMapState === "partial") {
    const note = document.createElement("span");
    note.className = "map-partial-note";
    note.textContent = currentLanguage === "hi" ? "कुछ ग्रिड पॉइंट उपलब्ध नहीं" : "Some grid points unavailable";
    pointsElement.append(note);
  }
}

async function fetchPollutionMap(latitude = selectedAirLocation.latitude, longitude = selectedAirLocation.longitude) {
  const requestId = ++pollutionMapRequestId;
  pollutionMapState = "loading";
  pollutionMapData = [];
  renderPollutionMap();

  const offsets = [[0, 0], [0.18, 0], [-0.18, 0], [0, 0.18], [0, -0.18]];
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 15000);
  try {
    const results = await Promise.allSettled(offsets.map(async ([latitudeOffset, longitudeOffset]) => {
      const query = new URLSearchParams({
        latitude: String(latitude + latitudeOffset),
        longitude: String(longitude + longitudeOffset),
        current: "us_aqi,pm2_5,pm10",
        timezone: "auto"
      });
      const response = await fetch(`https://air-quality-api.open-meteo.com/v1/air-quality?${query}`, {
        signal: controller.signal,
        cache: "no-store"
      });
      if (!response.ok) throw new Error(`Open-Meteo returned HTTP ${response.status}`);
      const data = await response.json();
      if (!data.current || !Number.isFinite(data.current.us_aqi)
        || !Number.isFinite(data.current.pm2_5) || !Number.isFinite(data.current.pm10)
        || typeof data.current.time !== "string"
        || !Number.isFinite(data.latitude) || !Number.isFinite(data.longitude)) {
        throw new Error("Open-Meteo response is missing map AQI or grid coordinates");
      }
      return data;
    }));
    if (requestId !== pollutionMapRequestId) return;

    const uniquePoints = new Map();
    results.forEach((result) => {
      if (result.status !== "fulfilled") return;
      const point = result.value;
      const key = `${point.latitude.toFixed(4)},${point.longitude.toFixed(4)}`;
      uniquePoints.set(key, point);
    });
    pollutionMapData = [...uniquePoints.values()];
    if (!pollutionMapData.length) throw new Error("Open-Meteo returned no usable model grid points");
    pollutionMapState = results.every((result) => result.status === "fulfilled") ? "live" : "partial";
    renderPollutionMap();
    console.info("AirGuard loaded CAMS model grid points for the pollution map.", {
      requestedPoints: offsets.length,
      availableGridPoints: pollutionMapData.length,
      time: pollutionMapData[0].current.time,
      gridCoordinates: pollutionMapData.map((point) => [point.latitude, point.longitude])
    });
  } catch (error) {
    if (requestId !== pollutionMapRequestId) return;
    pollutionMapData = [];
    pollutionMapState = "error";
    renderPollutionMap();
    console.error("AirGuard could not load pollution map model data.", error);
  } finally {
    clearTimeout(timeout);
  }
}

function useCurrentAirLocation() {
  if (!navigator.geolocation) {
    showToast(currentLanguage === "hi"
      ? "इस ब्राउज़र में स्थान सुविधा उपलब्ध नहीं है। नई दिल्ली का डेटा दिखाया जा रहा है।"
      : "Location is unavailable in this browser. Keeping Lucknow selected.");
    return;
  }
  showToast(currentLanguage === "hi" ? "आपका स्थान प्राप्त किया जा रहा है…" : "Getting your location…");
  navigator.geolocation.getCurrentPosition((position) => {
    selectedAirLocation = {
      name: { en: "Your location", hi: "आपकी जगह" },
      latitude: position.coords.latitude,
      longitude: position.coords.longitude
    };
    document.querySelector("#air-location-name").textContent = selectedAirLocation.name[currentLanguage];
    fetchCurrentAirQuality(selectedAirLocation.latitude, selectedAirLocation.longitude);
    fetchCurrentWeather(selectedAirLocation.latitude, selectedAirLocation.longitude);
    fetchPollutionMap(selectedAirLocation.latitude, selectedAirLocation.longitude);
    fetchAirQualityTimeline(selectedAirLocation.latitude, selectedAirLocation.longitude);
    fetchCustomMlForecast(selectedAirLocation.latitude, selectedAirLocation.longitude);
  }, (error) => {
    console.warn("AirGuard could not access the requested location.", {
      code: error.code,
      message: error.message
    });
    const message = error.code === error.PERMISSION_DENIED
      ? (currentLanguage === "hi"
        ? "स्थान की अनुमति नहीं मिली। ब्राउज़र साइट सेटिंग में स्थान की अनुमति दें।"
        : "Location permission was denied. Allow location in your browser’s site settings.")
      : (currentLanguage === "hi"
        ? "स्थान प्राप्त नहीं हो सका। नई दिल्ली का डेटा जारी रहेगा।"
        : "Could not get your location. Lucknow remains selected.");
    showToast(message);
  }, { enableHighAccuracy: false, timeout: 10000, maximumAge: 300000 });
}

function responseFor(text) {
  const query = text.toLowerCase();
  if (/forecast|tomorrow|later|kab|baad mein|kitne baje|when|पूर्वानुमान/.test(query)) {
    const points = getForecastPoints();
    if (!points.length) return assistantDataMessages[currentLanguage].forecast;
    const peak = points.reduce((highest, point) => point.aqi > highest.aqi ? point : highest, points[0]);
    return currentLanguage === "hi"
      ? `अगले 24 घंटों के CAMS मॉडल पूर्वानुमान में अधिकतम US AQI ${Math.round(peak.aqi)} (${peak.time.replace("T", " ")}, ${airQualityTimeline.timezone}) है। ये मॉडल अनुमान हैं, मापे गए अवलोकन नहीं।`
      : `The CAMS model forecast peaks at US AQI ${Math.round(peak.aqi)} (${peak.time.replace("T", " ")} ${airQualityTimeline.timezone}) in the next 24 hours. These are model estimates, not measured observations.`;
  }
  const asksForAdvice = /go|outside|run|walk|mask|bahar|jaun|jau|jog|health|safe|theek|kya kar/.test(query);
  const asksAboutAir = /aqi|pollution|hawa|air|quality|pollut|कैसी|कैसा/.test(query);
  if ((asksForAdvice || asksAboutAir) && currentAirQuality) {
    const aqi = Math.round(currentAirQuality.current.us_aqi);
    const category = airQualityCategory(aqi);
    if (currentLanguage === "hi") {
      return asksForAdvice
        ? `वर्तमान अनुमानित US AQI ${aqi} (${category}) है। यह Open-Meteo CAMS मॉडल का अनुमान है; बाहर की गतिविधि के लिए स्थानीय स्वास्थ्य सलाह देखें।`
        : `वर्तमान अनुमानित US AQI ${aqi} (${category}) है। यह Open-Meteo CAMS मॉडल पर आधारित है।`;
    }
    return asksForAdvice
      ? `The current model-estimated US AQI is ${aqi} (${category}). Check local health guidance before outdoor activity.`
      : `The current model-estimated US AQI is ${aqi} (${category}), based on Open-Meteo CAMS data.`;
  }
  if (asksForAdvice || asksAboutAir) return assistantDataMessages[currentLanguage].unavailable;
  return t("voiceFallback");
}

function loadSpeechVoices() {
  if (!("speechSynthesis" in window)) {
    console.error("AirGuard speech synthesis is unavailable in this browser.");
    return [];
  }

  const synthesis = window.speechSynthesis;
  try {
    availableVoices = synthesis.getVoices();
    if (!speechVoicesListenerInstalled) {
      synthesis.addEventListener("voiceschanged", () => {
        try {
          availableVoices = synthesis.getVoices();
        } catch (error) {
          console.error("AirGuard could not refresh speech voices.", error);
        }
      });
      speechVoicesListenerInstalled = true;
    }
  } catch (error) {
    console.error("AirGuard could not load speech voices.", error);
  }
  return availableVoices;
}

function speakAssistantResponse(message) {
  if (!("speechSynthesis" in window) || typeof SpeechSynthesisUtterance === "undefined") {
    console.error("AirGuard cannot speak: speech synthesis is unavailable.");
    return false;
  }

  const synthesis = window.speechSynthesis;
  const locale = currentLanguage === "hi" ? "hi-IN" : "en-IN";
  const languageCode = locale.slice(0, 2).toLowerCase();
  const voices = loadSpeechVoices();
  const voice = voices.find((item) => item.lang && item.lang.toLowerCase() === locale.toLowerCase())
    || voices.find((item) => item.lang && item.lang.toLowerCase().startsWith(`${languageCode}-`))
    || voices.find((item) => item.lang && item.lang.toLowerCase() === languageCode);

  try {
    const utterance = new SpeechSynthesisUtterance(message);
    utterance.lang = locale;
    utterance.rate = 1;
    utterance.volume = 1;
    if (voice) utterance.voice = voice;
    utterance.onerror = (event) => {
      console.error("AirGuard speech synthesis failed.", {
        error: event.error,
        message: event.message,
        language: locale,
        voice: voice ? voice.name : "browser default"
      });
    };

    synthesis.cancel();
    if (synthesis.paused) synthesis.resume();
    synthesis.speak(utterance);
    return true;
  } catch (error) {
    console.error("AirGuard could not start speech synthesis.", error);
    return false;
  }
}

function testAssistantSpeech() {
  const message = currentLanguage === "hi"
    ? "नमस्ते, यह AirGuard आवाज़ की जाँच है।"
    : "Hello, this is a test of the AirGuard voice assistant.";
  if (speakAssistantResponse(message)) showAssistantResponse(message);
}

function showAssistantResponse(message, speak = false, state = "success") {
  const response = document.querySelector("#assistant-response");
  document.querySelector("#assistant-response-status").textContent = t(state);
  response.dataset.state = state;
  document.querySelector("#assistant-response-text").textContent = message;
  response.hidden = false;
  if (speak) speakAssistantResponse(message);
}

function answerAssistantQuestion(question) {
  const transcript = question.trim();
  if (!transcript) {
    showAssistantResponse(currentLanguage === "hi" ? "कृपया पहले अपना प्रश्न लिखें।" : "Please enter a question first.", false, "error");
    return null;
  }
  const answer = responseFor(transcript);
  const label = currentLanguage === "hi" ? "आपने कहा:" : "You said:";
  showAssistantResponse(`${label} “${transcript}”\n${answer}`);
  return answer;
}

function microphoneErrorMessage(error) {
  const name = error && error.name ? error.name : error;
  if (name === "NotAllowedError" || name === "PermissionDeniedError" || name === "SecurityError") {
    return t("micPermission");
  }
  if (name === "NotFoundError" || name === "DevicesNotFoundError") {
    return currentLanguage === "hi" ? "कोई माइक्रोफ़ोन नहीं मिला। माइक्रोफ़ोन कनेक्शन जाँचें।" : "No microphone was found. Check your microphone connection.";
  }
  if (name === "NotReadableError" || name === "TrackStartError") return t("microphoneBusy");
  return recognitionErrorMessage("unknown");
}

function recognitionErrorMessage(error) {
  if (error === "not-allowed" || error === "service-not-allowed") return t("micPermission");
  if (currentLanguage === "hi") {
    if (error === "no-speech") return "आपकी आवाज़ सुनाई नहीं दी। कृपया फिर से बोलें।";
    if (error === "empty-result") return "आवाज़ पहचान से खाली जवाब मिला। कृपया फिर से बोलें या अपना प्रश्न लिखें।";
    if (error === "audio-capture") return t("microphoneBusy");
    if (error === "network") return "वॉइस पहचान सेवा से कनेक्ट नहीं हो सका। कृपया फिर से कोशिश करें।";
    if (error === "aborted") return "वॉइस पहचान रोक दी गई। शुरू करने के लिए फिर से दबाएँ।";
    return "वॉइस पहचान में समस्या हुई। कृपया फिर से कोशिश करें।";
  }
  if (error === "no-speech") return "I didn’t hear speech. Please try again.";
  if (error === "empty-result") return "Speech recognition returned an empty result. Please try again or type your question.";
  if (error === "audio-capture") return t("microphoneBusy");
  if (error === "network") return "The speech recognition service could not be reached. Please try again.";
  if (error === "aborted") return "Voice recognition stopped. Tap to start again.";
  return "Voice recognition failed. Please try again.";
}

async function startVoiceAssistant() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  const button = document.querySelector("#mic-button");
  console.info("AirGuard microphone button activated.", {
    recognitionSupported: Boolean(SpeechRecognition),
    language: currentLanguage === "hi" ? "hi-IN" : "en-IN",
    secureContext: window.isSecureContext,
    online: navigator.onLine
  });
  if (activeRecognition || voiceAssistantStarting) {
    console.info("AirGuard speech recognition is already active.");
    return;
  }
  if (window.isSecureContext === false) {
    console.error("AirGuard speech recognition requires HTTPS or localhost.");
    showAssistantResponse(currentLanguage === "hi"
      ? "वॉइस पहचान के लिए सुरक्षित कनेक्शन (HTTPS या localhost) का उपयोग करें।"
      : "Voice recognition requires a secure connection (HTTPS or localhost).", false, "error");
    return;
  }
  if (!SpeechRecognition) {
    console.error("AirGuard speech recognition is unavailable in this browser.");
    showAssistantResponse(t("speechUnsupported"), false, "error");
    return;
  }
  let recognition;
  try {
    recognition = new SpeechRecognition();
  } catch (error) {
    console.error("AirGuard could not create speech recognition.", error);
    showAssistantResponse(microphoneErrorMessage(error), false, "error");
    return;
  }

  voiceAssistantStarting = true;
  button.disabled = true;
  button.setAttribute("aria-busy", "true");
  button.classList.add("listening");
  button.querySelector("span").textContent = t("listening");
  showAssistantResponse(t("requestingMicrophone"), false, "listening");
  let mediaStream;
  try {
    if (navigator.mediaDevices && typeof navigator.mediaDevices.getUserMedia === "function") {
      mediaStream = await navigator.mediaDevices.getUserMedia({ audio: true });
    } else {
      console.warn("AirGuard MediaDevices is unavailable; speech recognition will request microphone access.");
    }

    activeRecognition = recognition;
    let assistantMessage;
    let recognitionError = false;
    let resultReceived = false;
    let ended = false;
    let recognitionTimeout;
    recognition.lang = currentLanguage === "hi" ? "hi-IN" : "en-IN";
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;
    const resetListening = () => {
      clearTimeout(recognitionTimeout);
      button.classList.remove("listening");
      button.querySelector("span").textContent = t("tapToSpeak");
      button.disabled = false;
      button.removeAttribute("aria-busy");
      if (activeRecognition === recognition) activeRecognition = null;
    };
    const finishRecognition = () => {
      if (ended) return;
      ended = true;
      resetListening();
      console.info("AirGuard speech recognition ended.", {
        transcriptReceived: resultReceived,
        language: recognition.lang
      });
      if (assistantMessage) speakAssistantResponse(assistantMessage);
      else if (!resultReceived && !recognitionError) {
        showAssistantResponse(recognitionErrorMessage("no-speech"), false, "error");
      }
    };
    recognition.onstart = (event) => {
      console.info("AirGuard speech recognition event: start.", { language: recognition.lang, event });
      recognitionTimeout = setTimeout(() => {
        if (ended) return;
        console.warn("AirGuard speech recognition timed out.", { language: recognition.lang });
        recognitionError = true;
        showAssistantResponse(recognitionErrorMessage("no-speech"), false, "error");
        try {
          recognition.stop();
        } catch (error) {
          console.error("AirGuard could not stop timed-out speech recognition.", error);
          finishRecognition();
        }
      }, 30000);
    };
    recognition.onaudiostart = (event) => console.info("AirGuard speech recognition event: audiostart.", event);
    recognition.onsoundstart = (event) => console.info("AirGuard speech recognition event: soundstart.", event);
    recognition.onspeechstart = (event) => console.info("AirGuard speech recognition event: speechstart.", event);
    recognition.onresult = (event) => {
      const results = Array.from(event.results || []);
      const transcript = results.slice(event.resultIndex || 0).map((result) => {
        const alternative = result && result[0];
        return alternative && typeof alternative.transcript === "string" ? alternative.transcript : "";
      }).join(" ").trim();
      console.info("AirGuard speech recognition result.", {
        transcript,
        resultCount: results.length,
        resultIndex: event.resultIndex
      });
      if (!transcript) {
        recognitionError = true;
        console.warn("AirGuard speech recognition returned an empty result.", event);
        showAssistantResponse(recognitionErrorMessage("empty-result"), false, "error");
        return;
      }
      resultReceived = true;
      showAssistantResponse(t("processing"), false, "processing");
      setTimeout(() => {
        assistantMessage = answerAssistantQuestion(transcript);
        if (ended && assistantMessage) speakAssistantResponse(assistantMessage);
      }, 120);
    };
    recognition.onnomatch = (event) => {
      recognitionError = true;
      console.warn("AirGuard speech recognition event: nomatch.", event);
      showAssistantResponse(recognitionErrorMessage("no-speech"), false, "error");
    };
    recognition.onerror = (event) => {
      if (event.error === "aborted" && recognitionError) return;
      recognitionError = true;
      console.error("AirGuard speech recognition failed.", {
        error: event.error,
        message: event.message,
        language: recognition.lang,
        online: navigator.onLine,
        secureContext: window.isSecureContext
      });
      showAssistantResponse(recognitionErrorMessage(event.error), false, "error");
      resetListening();
    };
    recognition.onaudioend = (event) => console.info("AirGuard speech recognition event: audioend.", event);
    recognition.onsoundend = (event) => console.info("AirGuard speech recognition event: soundend.", event);
    recognition.onspeechend = (event) => console.info("AirGuard speech recognition event: speechend.", event);
    recognition.onend = finishRecognition;
    recognition.start();
  } catch (error) {
    console.error("AirGuard could not start speech recognition.", error);
    activeRecognition = null;
    button.classList.remove("listening");
    button.querySelector("span").textContent = t("tapToSpeak");
    button.disabled = false;
    button.removeAttribute("aria-busy");
    showAssistantResponse(microphoneErrorMessage(error), false, "error");
  } finally {
    if (mediaStream) mediaStream.getTracks().forEach((track) => track.stop());
    voiceAssistantStarting = false;
    button.removeAttribute("aria-busy");
  }
}

