if ("IntersectionObserver" in window) {
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        const navLink = document.querySelector(`.nav-link[data-section="${entry.target.id}"]`);
        if (navLink) document.querySelectorAll(".nav-link").forEach((link) => link.classList.toggle("active", link === navLink));
      }
    });
  }, { rootMargin: "-20% 0px -65% 0px" });
  document.querySelectorAll(".main-content > .page-content > section[id]").forEach((section) => observer.observe(section));
}
